//! Windows process observation for the owned no-provider watcher.
use std::{sync::{mpsc,Arc,atomic::{AtomicU64,Ordering}},time::{Duration,SystemTime,UNIX_EPOCH}};
use serde_json::Value;
pub struct WatchState{running:bool,started:Option<u64>}
impl WatchState{fn new()->Self{Self{running:false,started:None}}fn observe(&mut self,now:u64,running:bool)->(bool,Duration){let closed=!running&&self.running;let check=closed&&self.started.is_some_and(|start|now.saturating_sub(start)>1_200_000);if closed{self.started=None}if running&&self.started.is_none(){self.started=Some(now)}self.running=running;(check,Duration::from_secs(if running{5}else{30}))}}
fn observed_game()->Result<bool,String>{use windows_sys::Win32::{Foundation::{CloseHandle,INVALID_HANDLE_VALUE,GetLastError,ERROR_NO_MORE_FILES},System::Diagnostics::ToolHelp::{CreateToolhelp32Snapshot,Process32FirstW,Process32NextW,PROCESSENTRY32W,TH32CS_SNAPPROCESS}};unsafe{let h=CreateToolhelp32Snapshot(TH32CS_SNAPPROCESS,0);if h==INVALID_HANDLE_VALUE{return Err("process snapshot unavailable; watcher outcome unconfirmed".into())}let result=(||{let mut p=PROCESSENTRY32W::default();p.dwSize=std::mem::size_of::<PROCESSENTRY32W>() as u32;if Process32FirstW(h,&mut p)==0{return Err("process enumeration unavailable; watcher outcome unconfirmed".to_string())}loop{let end=p.szExeFile.iter().position(|x|*x==0).unwrap_or(p.szExeFile.len());let name=String::from_utf16_lossy(&p.szExeFile[..end]);if name.contains("csgo.exe")||name.contains("cs2.exe"){return Ok(true)}if Process32NextW(h,&mut p)==0{let error=GetLastError();if error==ERROR_NO_MORE_FILES{return Ok(false)}return Err(format!("process enumeration failed: {error}"))}}})();if CloseHandle(h)==0{return Err("process snapshot close unconfirmed".into())}result}}
pub fn run(rx:mpsc::Receiver<()>,load:&dyn Fn()->Result<Value,String>,ready:mpsc::SyncSender<Result<(),String>>,samples:Arc<AtomicU64>)->Result<(),String>{match observed_game(){Ok(_)=>{let _=ready.send(Ok(()));},Err(e)=>{let _=ready.send(Err(e.clone()));return Err(e)}}let mut state=WatchState::new();let mut delay=Duration::from_secs(30);loop{match rx.recv_timeout(delay){Ok(())|Err(mpsc::RecvTimeoutError::Disconnected)=>return Ok(()),Err(mpsc::RecvTimeoutError::Timeout)=>{let running=observed_game()?;samples.fetch_add(1,Ordering::AcqRel);let now=SystemTime::now().duration_since(UNIX_EPOCH).map_err(|_|"clock before epoch")?.as_millis().try_into().map_err(|_|"clock out of range")?;let(check,next)=state.observe(now,running);delay=next;if check{let settings=load()?;for provider in ["Valve","Faceit","5EPlay","Renown"]{let key=format!("download{provider}DemosInBackground");if settings["download"].get(&key).and_then(Value::as_bool)!=Some(false){return Err(format!("owned fixture does not support {key}"))}}}}}}}
#[cfg(test)]mod tests{use super::*;use serde_json::{Value,json};#[test]fn original_running_closed_timing_oracle(){let oracle:Value=serde_json::from_str(include_str!("../tests/fixtures/pg80-original-watcher-oracle.json")).unwrap();let mut s=WatchState::new();assert_eq!(s.observe(1000,true),(false,Duration::from_secs(5)));assert_eq!(s.observe(1_201_001,false),(true,Duration::from_secs(30)));assert!(oracle["trace"].as_array().unwrap().contains(&json!("interval:5000")));assert!(oracle["trace"].as_array().unwrap().contains(&json!("settings")));let mut s=WatchState::new();s.observe(1000,true);assert!(!s.observe(1_201_000,false).0);}}
